extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi correttamente"):
		return

	var mesh_west := find_by_name(main, "MeshWest") as MeshInstance3D
	if not check("mesh_west_exists", mesh_west != null, "In BlockWest serve un figlio MeshInstance3D chiamato MeshWest"):
		return
	var box_west := mesh_west.mesh as BoxMesh
	if check("box_west_mesh", box_west != null, "MeshWest deve usare una BoxMesh"):
		check("box_west_size", box_west.size == Vector3(3, 1, 3), "La BoxMesh di MeshWest deve avere Size = Vector3(3, 1, 3) (trovato %s)" % str(box_west.size))

	var mat_plastic := mesh_west.material_override as StandardMaterial3D
	if check("mat_plastic_exists", mat_plastic != null, "MeshWest deve avere uno StandardMaterial3D in Material Override"):
		check("plastic_metallic", absf(mat_plastic.metallic - 0.0) < 0.05, "La plastica deve avere Metallic = 0.0 (trovato %.2f)" % mat_plastic.metallic)
		check("plastic_roughness", absf(mat_plastic.roughness - 0.3) < 0.05, "La plastica deve avere Roughness = 0.3 (trovato %.2f)" % mat_plastic.roughness)

	var mesh_bridge := find_by_name(main, "MeshBridge") as MeshInstance3D
	if not check("mesh_bridge_exists", mesh_bridge != null, "In BlockWestBridge serve un figlio MeshInstance3D chiamato MeshBridge"):
		return
	var box_bridge := mesh_bridge.mesh as BoxMesh
	if check("box_bridge_mesh", box_bridge != null, "MeshBridge deve usare una BoxMesh"):
		check("box_bridge_size", box_bridge.size == Vector3(2, 0.2, 4), "La BoxMesh di MeshBridge deve avere Size = Vector3(2, 0.2, 4) (trovato %s)" % str(box_bridge.size))

	var mat_glass := mesh_bridge.material_override as StandardMaterial3D
	if check("mat_glass_exists", mat_glass != null, "MeshBridge deve avere uno StandardMaterial3D in Material Override"):
		check("glass_transparency", mat_glass.transparency == BaseMaterial3D.TRANSPARENCY_ALPHA, "Il vetro deve avere Transparency impostata su Alpha")
		check("glass_alpha", mat_glass.albedo_color.a < 0.5, "Il vetro deve avere un valore Alfa di Albedo ridotto (trovato %.2f)" % mat_glass.albedo_color.a)
		check("glass_roughness", absf(mat_glass.roughness - 0.05) < 0.05, "Il vetro deve avere Roughness = 0.05 (trovato %.2f)" % mat_glass.roughness)

